import { PrismaClient } from '@prisma/client';
import { decryptSecret } from './lib/crypto-box.ts';
import { Client } from 'ssh2';
const EXPECT_IP = '51.79.226.200';
const db = new PrismaClient();
const s = await db.server.findUnique({ where: { id: 'cmsc9l72y000ghl7iyd87u5ja' } });
await db.$disconnect();
if (!s) { console.error('NO SERVER ROW'); process.exit(1); }
if (s.ipAddress !== EXPECT_IP) { console.error('IP MISMATCH! got', s.ipAddress); process.exit(1); }
const password = decryptSecret(s.rootPasswordEnc) ?? s.rootPassword;
if (!password) { console.error('NO PW'); process.exit(1); }
const cmd = process.env.RCMD;
if (!cmd) { console.error('NO RCMD'); process.exit(1); }
const conn = new Client();
function run() {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return reject(err);
      let out='', errout='';
      stream.on('close', (code) => resolve({code,out,errout}))
        .on('data', d => out += d.toString())
        .stderr.on('data', d => errout += d.toString());
    });
  });
}
conn.on('ready', async () => {
  try { const r = await run(); process.stdout.write(r.out); if(r.errout) process.stderr.write('\n[STDERR]\n'+r.errout); process.stderr.write(`\n[EXIT ${r.code}]\n`); }
  catch(e){ console.error('EXEC ERR', e.message); }
  finally { conn.end(); }
}).on('error', e => { console.error('SSH ERR', e.message); process.exit(1); })
.connect({ host: s.ipAddress, port: s.sshPort || 22, username: 'root', password, readyTimeout: 15000 });
