    public decimal TotalGross { get; set; }
    public decimal TotalDiscount { get; set; }
    public decimal TotalTax { get; set; }
    public decimal TotalNet { get; set; }

    [BsonRepresentation(BsonType.ObjectId)]
    public string? RefereePartnerId { get; set; }
    public string Status { get; set; } = "PAID"; // "PAID", "PARTIAL", "PENDING"
    public string? Notes { get; set; } // General transaction notes

    /// <summary>
    /// Top-level payment method for this invoice. Stamped when the invoice is
    /// settled: "CREDIT" (package), "STRIPE", "CASH", "BANK_TRANSFER", etc.
    /// Null on old invoices and on unpaid/partial invoices where multiple
    /// methods may apply. Used by the UI to show a "Paid via package credit"
    /// indicator instead of "No payments recorded" for 0đ credit invoices.
    /// </summary>
    public string? PaymentMethod { get; set; }

    /// <summary>
    /// Set by <see cref="SoulPilates.Core.Interfaces.IVoucherService.RedeemAsync"/>
    /// when a voucher is applied at POS. Null on every other invoice.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? VoucherRedemptionId { get; set; }

    /// <summary>
    /// Set by <see cref="SoulPilates.Core.Interfaces.IPromotionService.RedeemAsync"/>
    /// when a customer-entered promo code is applied. Null when no promo
    /// was used. Distinct from <see cref="VoucherRedemptionId"/> so both
    /// layers can stack on the same invoice.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? PromoRedemptionId { get; set; }

    /// <summary>
    /// Stamped by <c>InvoiceService.DeductStockForMerchandiseLinesAsync</c> the
    /// first time the invoice flips into <c>PAID</c> and merchandise stock is
    /// deducted. Used as an idempotency latch so a PARTIAL→PAID transition,
    /// or any subsequent payment that re-evaluates the invoice, doesn't
    /// double-decrement <see cref="MerchandiseSku.StockQuantity"/>.
    /// </summary>
    public DateTime? StockDeductedAt { get; set; }

    /// <summary>
    /// Online processing surcharge (Stripe fee) collected from the customer
    /// on top of the class/product value. Populated by
    /// <c>PaymentService.CreateBookingInvoiceAsync</c> when the booking was
    /// paid via STRIPE_DEPOSIT or STRIPE_FULL and the admin has configured
    /// <see cref="GlobalSettings.OnlinePaymentFeePercentage"/> &gt; 0.
    /// Zero for POS, credit, or cash invoices. Not included in TotalNet
    /// (which reflects the product value only) — shown as a separate line
    /// item on the receipt for transparency.
    /// </summary>
    public decimal OnlineFeeAmount { get; set; }

    public List<InvoiceLine> Lines { get; set; } = new List<InvoiceLine>();
}

