    public async Task<IActionResult> AddPayment(string id, [FromBody] AddPaymentRequest req)
    {
        if (req is null) return BadRequest(new { error = "Body is required." });
        if (req.AmountPaid <= 0m) return BadRequest(new { error = "amountPaid must be greater than zero." });

        var payment = new Payment
        {
            AmountPaid = req.AmountPaid,
            PaymentDate = req.PaymentDate ?? DateTime.UtcNow,
            PaymentMethod = string.IsNullOrWhiteSpace(req.PaymentMethod) ? "CASH" : req.PaymentMethod,
        };

        try
        {
            var result = await _invoiceService.AddPaymentAsync(id, payment);
            return Ok(result);
        }
        catch (SoulPilates.Core.Exceptions.InsufficientStockException ex)
        {
            // P3-S14: 409 lets the POS keep the cart intact so the receptionist
            // can remove the offending line or wait for a restock.
            return Conflict(new
            {
                error = ex.Message,
                skuId = ex.SkuId,
                requested = ex.Requested,
                available = ex.Available,
            });
        }
    }

