    public async Task<List<PaymentMethodDistributionDto>> GetPaymentMethodDistributionAsync(AnalyticsRangeQuery range)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));

        var attendances = await _attendances
            .Find(Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.Gte(a => a.BookedAt, range.StartDate),
                Builders<Attendance>.Filter.Lt(a => a.BookedAt, range.EndDate),
                Builders<Attendance>.Filter.In(a => a.Status, ActiveBookedStatuses)))
            .Project(a => new { a.PaymentMethod, a.AmountPaid })
            .ToListAsync();

        if (attendances.Count == 0) return new List<PaymentMethodDistributionDto>();

        var total = attendances.Count;
        return attendances
            .GroupBy(a => a.PaymentMethod ?? "UNKNOWN")
            .Select(g => new PaymentMethodDistributionDto
            {
                Method = g.Key,
                BookingCount = g.Count(),
                RevenueVnd = g.Sum(a => a.AmountPaid ?? 0m),
                Share = Math.Round((decimal)g.Count() / total, 4),
            })
            .OrderByDescending(r => r.BookingCount)
            .ToList();
    }

