    public async Task<int> SendDueRemindersAsync(DateTime nowUtc, CancellationToken ct = default)
    {
        var s = await _settings.GetAsync(ct);
        if (!s.EnableRetentionReminders) return 0;

        var windows = (s.RetentionReminderWindows ?? new())
            .Select(w => (Tag: w, Days: ParseDays(w)))
            .Where(p => p.Days > 0)
            .OrderByDescending(p => p.Days) // Send the largest-gap reminder first so older inactivity gets the firmer copy.
            .ToList();

        if (windows.Count == 0) return 0;

        var sent = 0;
        foreach (var (tag, days) in windows)
        {
            // A package is eligible for window `tag` when:
            //   - It is currently active (status ACTIVE/LOW_BALANCE — not expired/completed).
            //   - CreditsRemaining ≥ configured floor — exhausted packs belong on a re-buy nudge, not a retention nudge.
            //   - Its last CHECKED_IN attendance is older than `days` (or there's no check-in ever).
            //   - This `tag` is not already on RetentionRemindersSent.
            var filter = Builders<ClientPackage>.Filter.And(
                Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
                Builders<ClientPackage>.Filter.Gte(p => p.CreditsRemaining, s.RetentionReminderMinCreditsRemaining),
                Builders<ClientPackage>.Filter.Not(Builders<ClientPackage>.Filter.AnyEq(p => p.RetentionRemindersSent, tag))
            );

            // Fetch in batches to avoid loading the full catalogue at once. A studio with
            // ~5k active packages stays comfortable in this range; tune via PageSize if
            // we ever get an order of magnitude bigger.
            var cursor = await _packages.Find(filter).ToCursorAsync(ct);
            while (await cursor.MoveNextAsync(ct))
            {
                foreach (var pkg in cursor.Current)
                {
                    if (ct.IsCancellationRequested) return sent;

                    // Most-recent CHECKED_IN attendance for this client. We sort by BookedAt;
                    // the booking flow stamps BookedAt at booking time and we have no separate
                    // "checked-in at" column, so this is the best proxy. If a client has never
                    // checked in we treat ActivationDate as their effective start.
                    var lastCheckIn = await _attendances
                        .Find(a => a.ClientId == pkg.ClientId && a.Status == "CHECKED_IN")
                        .SortByDescending(a => a.BookedAt)
                        .Limit(1)
                        .FirstOrDefaultAsync(ct);

                    var anchor = lastCheckIn?.BookedAt ?? pkg.ActivationDate;
                    var inactiveDays = (nowUtc - anchor).TotalDays;
                    if (inactiveDays < days) continue;

                    var client = await _clients.Find(c => c.Id == pkg.ClientId)
                        .FirstOrDefaultAsync(ct);
                    if (client is null || string.IsNullOrWhiteSpace(client.Email) || client.RetentionRemindersOptedOut)
                    {
                        // No email, or opted-out = silently tag so we don't re-query forever, skip the send.
                        await TagSentAsync(pkg.Id, tag, ct);
                        continue;
                    }

                    try
                    {
                        // Ensure a stable, unguessable token for the one-click unsubscribe link.
                        var unsubToken = client.UnsubscribeToken;
                        if (string.IsNullOrWhiteSpace(unsubToken))
                        {
                            unsubToken = Guid.NewGuid().ToString("N");
                            await _clients.UpdateOneAsync(
                                c => c.Id == client.Id,
                                Builders<Client>.Update.Set(c => c.UnsubscribeToken, unsubToken),
                                cancellationToken: ct);
                        }
                        var unsubUrl = $"{_publicBaseUrl}/api/retention/unsubscribe?token={unsubToken}";

                        var subject = $"We miss you at Soul Pilates";
                        var heading = $"Hi {FirstName(client.FullName)}, your mat is waiting";
                        var expiryLine = pkg.ExpiryDate.HasValue
                            ? $" (expires {pkg.ExpiryDate.Value:MMM d})"
                            : string.Empty;
                        var body =
                            $"It's been about {Math.Floor(inactiveDays):0} days since your last class and your package " +
                            $"still has {pkg.CreditsRemaining} credit{(pkg.CreditsRemaining == 1 ? "" : "s")}" +
                            $"{expiryLine}. Pick a class that fits your week — we'd love to see you on the reformer." +
                            $"\n\nPrefer not to receive these check-in reminders? Unsubscribe: {unsubUrl}";
                        await _emailService.SendGenericAsync(
                            client.Email,
                            subject,
                            heading,
                            body,
                            ctaUrl: $"{_publicBaseUrl}/schedule",
                            ctaLabel: "Book a class");

                        await TagSentAsync(pkg.Id, tag, ct);
                        sent++;
                    }
                    catch (Exception ex)
                    {
                        // Leave the tag off so the next tick retries. We log per-package
                        // rather than rethrow because one bad address shouldn't halt the
                        // remaining fan-out.
                        _logger.LogWarning(ex,
                            "RetentionReminderService email send failed for package {PackageId} window {Tag}",
                            pkg.Id, tag);
                    }
                }
            }
        }

        if (sent > 0)
            _logger.LogInformation("RetentionReminderService dispatched {Count} emails at {Now:o}", sent, nowUtc);
        return sent;
    }

    public async Task<bool> UnsubscribeByTokenAsync(string token, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(token)) return false;
        var result = await _clients.UpdateOneAsync(
            c => c.UnsubscribeToken == token,
            Builders<Client>.Update.Set(c => c.RetentionRemindersOptedOut, true),
            cancellationToken: ct);
        return result.MatchedCount > 0;
    }

    private Task TagSentAsync(string packageId, string tag, CancellationToken ct) =>
        _packages.UpdateOneAsync(
            p => p.Id == packageId,
            Builders<ClientPackage>.Update.Push(p => p.RetentionRemindersSent, tag),
            cancellationToken: ct);

    /// <summary>
    /// Parse window-tag strings of the form <c>"14d"</c> / <c>"30d"</c> into a day count.
    /// Unknown / unparseable tags return 0 so the dispatcher skips them defensively
    /// rather than crashing — this keeps the admin UI honest if a typo sneaks in.
    /// </summary>
    private static int ParseDays(string tag)
    {
        if (string.IsNullOrWhiteSpace(tag)) return 0;
        var t = tag.Trim().ToLowerInvariant();
        var suffix = t.EndsWith("d") ? t[..^1] : t;
        return int.TryParse(suffix, out var n) && n > 0 ? n : 0;
    }

    private static string FirstName(string? full) =>
        string.IsNullOrWhiteSpace(full) ? "there" : full.Split(' ')[0];
}

